     const properties=owned.length?owned.map(({space,index})=>`<button type="button" class="mono-seat-property" data-manage-property="${index}" aria-label="إدارة ${escapeHtml(space.name)}، ${escapeHtml(player.name)}">${escapeHtml(space.name)}${state.ownership[index].hotel?' · فندق':state.ownership[index].houses?` · ${digits.format(state.ownership[index].houses)} بيوت`:''}</button>`).join(''):'<span class="mono-no-properties">لا أملاك حتى الآن</span>';
     const classes='mono-player-seat '+(current?'current ':'')+(player.bankrupt?'bankrupt':'');
