 function playCue(kind,key){if(soundMuted||!key||playedSoundKeys.has(key))return;playedSoundKeys.add(key);if(playedSoundKeys.size>80)playedSoundKeys.delete(playedSoundKeys.values().next().value);try{const AudioCtor=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AudioCtor)return;soundContext??=new AudioCtor();if(soundContext.state==='suspended')void soundContext.resume().catch(()=>{});const pattern={roll:[360,520],reveal:[420,620],payment:[520,370],reward:[500,700],confirm:[540,760]}[kind]||[460,620],start=soundContext.currentTime;pattern.forEach((frequency,index)=>{const oscillator=soundContext.createOscillator(),gain=soundContext.createGain(),at=start+index*.095;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(.035,at+.018);gain.gain.exponentialRampToValueAtTime(.0001,at+.09);oscillator.connect(gain);gain.connect(soundContext.destination);oscillator.start(at);oscillator.stop(at+.1);});}catch{}}
